import React from "react";

export default function Footer({ t, go }) {
  const currentYear = new Date().getFullYear();

  return (
    <footer style={{
      borderTop: `1px solid ${t.border}`,
      background: t.surface,
      padding: "24px 28px",
      marginTop: "auto"
    }}>
      <div style={{
        maxWidth: 1200,
        margin: "0 auto",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        flexWrap: "wrap",
        gap: 16
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontWeight: 800, fontSize: 14, color: t.text }}>
            Nyaya<span style={{ color: t.blue }}>Setu</span>
          </span>
          <span style={{ color: t.sub, fontSize: 12 }}>
            © {currentYear} — AI-powered legal utilities for Indian citizens
          </span>
        </div>

        <div style={{ display: "flex", gap: 20 }}>
          {["Home", "Dashboard", "Research", "Editor"].map(link => (
            <button
              key={link}
              onClick={() => go(link.toLowerCase())}
              style={{
                background: "none",
                border: "none",
                color: t.sub,
                fontSize: 12,
                fontWeight: 600,
                cursor: "pointer",
                transition: "color 0.15s"
              }}
              onMouseEnter={e => e.currentTarget.style.color = t.text}
              onMouseLeave={e => e.currentTarget.style.color = t.sub}
            >
              {link}
            </button>
          ))}
        </div>
      </div>
    </footer>
  );
}
